<?php
declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$accounts=[];$rows=[];$selected=(int)($_GET['account']??0);$from=trim((string)($_GET['from']??date('Y-m-01')));$to=trim((string)($_GET['to']??date('Y-m-t')));$opening=0.0;$closing=0.0;$inflow=0.0;$outflow=0.0;
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$accounts=finance_step16_accounts($pdo,$orgId);if($selected<=0&&$accounts)$selected=(int)$accounts[0]['id'];$from=finance_step16_date($from,'from date');$to=finance_step16_date($to,'to date');if($selected>0){$cash=finance_step16_cash($pdo,$orgId,$selected);$before=(new DateTimeImmutable($from))->modify('-1 day')->format('Y-m-d');$opening=finance_step16_cash_balance($pdo,$orgId,$selected,$before);$stmt=$pdo->prepare("SELECT j.journal_date,j.journal_number,j.journal_type,j.memo,j.source_code,j.source_type,l.id journal_line_id,l.debit_amount,l.credit_amount,l.line_memo,a.account_name FROM finance_journal_lines l JOIN finance_journals j ON j.id=l.journal_id AND j.organization_id=l.organization_id JOIN finance_ledger_accounts a ON a.id=l.ledger_account_id AND a.organization_id=l.organization_id WHERE l.organization_id=? AND l.cash_account_id=? AND j.journal_date BETWEEN ? AND ? ORDER BY j.journal_date,j.id,l.line_no");$stmt->execute([$orgId,$selected,$from,$to]);$raw=$stmt->fetchAll();$balance=$opening;foreach($raw as $r){$movement=round((float)$r['debit_amount']-(float)$r['credit_amount'],2);$balance=round($balance+$movement,2);$r['movement']=$movement;$r['running_balance']=$balance;if($movement>=0)$inflow+=$movement;else$outflow+=abs($movement);$rows[]=$r;}$closing=$balance;}}catch(Throwable $e){$error=$e->getMessage();}
function cb_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function cb_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Cashbook - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Cashbook / Bankbook</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_accounts.php">Accounts</a><a class="os-btn" href="finance_reconciliation.php">Reconcile</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Finance</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a href="finance_journal.php"><i class="dot"></i>Journal</a><a class="active" href="finance_cashbook.php"><i class="dot"></i>Cashbook</a><a href="finance_cash_flow.php"><i class="dot"></i>Cash Flow</a><a href="finance_reconciliation.php"><i class="dot"></i>Reconciliation</a></nav></aside><main class="os-main"><section class="os-hero s10-hero"><div class="os-kicker">STEP 16D • CASHBOOK / BANKBOOK</div><h1>Track every liquid-account movement with a running balance.</h1><p>Clearing accounts remain visible until transactions are reclassified/reconciled to actual accounts.</p></section><section class="os-card" style="margin-top:14px"><form method="get" class="pp-form"><label>Account<select name="account"><?php foreach($accounts as $a):?><option value="<?= (int)$a['id'] ?>" <?= $selected===(int)$a['id']?'selected':'' ?>><?= cb_h($a['account_name'].($a['is_system_clearing']?' • Clearing':'')) ?></option><?php endforeach;?></select></label><label>From<input type="date" name="from" value="<?= cb_h($from) ?>"></label><label>To<input type="date" name="to" value="<?= cb_h($to) ?>"></label><button>View</button></form></section><?php if($error):?><div class="pp-alert bad"><strong>Cashbook diagnostic:</strong> <?= cb_h($error) ?></div><?php else:?><section class="s10-kpis"><div class="s10-kpi"><small>Opening</small><strong><?= cb_m($opening) ?></strong></div><div class="s10-kpi"><small>Inflow</small><strong><?= cb_m($inflow) ?></strong></div><div class="s10-kpi"><small>Outflow</small><strong><?= cb_m($outflow) ?></strong></div><div class="s10-kpi"><small>Closing</small><strong><?= cb_m($closing) ?></strong></div></section><section class="os-card" style="margin-top:14px"><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Journal</th><th>Source</th><th>Memo</th><th>In</th><th>Out</th><th>Balance</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= cb_h($r['journal_date']) ?></td><td><b><?= cb_h($r['journal_number']) ?></b><small><?= cb_h($r['journal_type']) ?></small></td><td><?= cb_h($r['source_code']?:'—') ?><small><?= cb_h($r['source_type']?:'manual') ?></small></td><td><?= cb_h($r['line_memo']?:$r['memo']?:'—') ?></td><td><?= $r['movement']>0?cb_m($r['movement']):'—' ?></td><td><?= $r['movement']<0?cb_m(abs($r['movement'])):'—' ?></td><td><b><?= cb_m($r['running_balance']) ?></b></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No cashbook movement in this period.</td></tr><?php endif;?></tbody></table></div></section><div class="os-footer-note"><strong>Running balance:</strong> Opening balance + posted journal debits − credits for the selected cash/bank account.</div><?php endif;?></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
